func novelExtractTags(data string) []string {
	var obj map[string]any
	_ = json.Unmarshal([]byte(data), &obj)
	raw, ok := obj["tags"]
	if !ok || raw == nil {
		return nil
	}
	seen := map[string]bool{}
	add := func(s string) {
		s = strings.ToLower(strings.TrimSpace(s))
		if s != "" {
			seen[s] = true
		}
	}
	switch t := raw.(type) {
	case map[string]any:
		for k := range t {
			add(k)
		}
	case []any:
		for _, v := range t {
			switch x := v.(type) {
			case string:
				add(x)
			case map[string]any:
				add(novelString(x, "key", "name"))
			}
		}
	}
	out := make([]string, 0, len(seen))
	for tag := range seen {
		out = append(out, tag)
	}
	sort.Strings(out)
	return out
}

func novelSharedStrings(a, b []string) []string {
	set := map[string]bool{}
	for _, s := range a {
		set[s] = true
	}
	out := make([]string, 0)
	for _, s := range b {
		if set[s] {
			out = append(out, s)
		}
	}
	sort.Strings(out)
	return out
}

func novelLoadConnectionDocs(cmd *cobra.Command) ([]novelConnectionDoc, error) {
	exists, err := novelLocalStoreExists(cmd)
	if err != nil {
		return nil, err
	}
	if !exists {
		return []novelConnectionDoc{}, nil
	}
	db, err := novelOpenStore(cmd)
	if err != nil {
		return nil, err
	}
	defer db.Close()
	rows, err := db.DB().Query(`SELECT id, title, author, COALESCE(source_url, url), summary, data, saved_at FROM documents WHERE COALESCE(parent_id, '') = '' ORDER BY id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	docs := make([]novelConnectionDoc, 0)
	for rows.Next() {
		doc, err := novelScanConnectionDoc(rows)
		if err != nil {
			return nil, err
		}
		docs = append(docs, doc)
	}
	return docs, rows.Err()
}

func novelLoadEngagedDocs(db *store.Store, all bool) ([]novelConnectionDoc, int, error) {
	var total int
	if err := db.DB().QueryRow(`SELECT COUNT(*) FROM documents WHERE COALESCE(parent_id, '') = ''`).Scan(&total); err != nil {
		return nil, 0, err
	}
	query := `SELECT id, title, author, COALESCE(source_url, url), summary, data, saved_at FROM documents WHERE COALESCE(parent_id, '') = ''`
	if !all {
		query += ` AND (
			(json_type(json_extract(data, '$.tags')) = 'object' AND json_extract(data, '$.tags') <> '{}')
			OR (json_type(json_extract(data, '$.tags')) = 'array' AND json_array_length(json_extract(data, '$.tags')) > 0)
			OR COALESCE(last_opened_at, '') <> ''
			OR COALESCE(reading_progress, 0) > 0
		)`
	}
	query += ` ORDER BY id`
	rows, err := db.DB().Query(query)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	docs := make([]novelConnectionDoc, 0)
	for rows.Next() {
		doc, err := novelScanConnectionDoc(rows)
		if err != nil {
			return nil, 0, err
		}
		docs = append(docs, doc)
	}
	return docs, total, rows.Err()
}

type novelConnectionDocScanner interface {
	Scan(dest ...any) error
}

func novelScanConnectionDoc(row novelConnectionDocScanner) (novelConnectionDoc, error) {
	var id string
	var title, author, url, summary, data, saved sql.NullString
	if err := row.Scan(&id, &title, &author, &url, &summary, &data, &saved); err != nil {
		return novelConnectionDoc{}, err
	}
	return novelConnectionDoc{
		ID:      id,
		SavedAt: novelParseTime(saved.String),
		Title:   cliutil.CleanText(title.String),
		Author:  cliutil.CleanText(author.String),
		URL:     strings.TrimSpace(url.String),
		Summary: cliutil.CleanText(summary.String),
		Tags:    novelExtractTags(data.String),
	}, nil
}

func novelConnectionTermDF(docs []novelConnectionDoc) map[string]int {
	df := map[string]int{}
	for _, doc := range docs {
		for _, term := range novelTokens(doc.Title, doc.Summary) {
			df[term]++
		}
	}
	return df
}

func novelSignificantConnectionTerms(doc novelConnectionDoc, df map[string]int, total int) []string {
	terms := novelTokens(doc.Title, doc.Summary)
	out := make([]string, 0, len(terms))
	for _, term := range terms {
		if total > 0 && float64(df[term])/float64(total) > 0.15 {
			continue
		}
		out = append(out, term)
	}
	return out
}

func novelConnectionTagDF(docs []novelConnectionDoc) map[string]int {
	df := map[string]int{}
	for _, doc := range docs {
		for _, tag := range doc.Tags {
			df[tag]++
		}
	}
	return df
}

func novelConnectionAuthorDF(docs []novelConnectionDoc) map[string]int {
	df := map[string]int{}
	for _, doc := range docs {
		author := strings.ToLower(strings.TrimSpace(doc.Author))
		if author != "" {
			df[author]++
		}
	}
	return df
}

func novelConnectionDFSurvives(df int, total int) bool {
	return total <= 0 || float64(df)/float64(total) <= 0.15
}

func novelDFSurvivingTags(doc novelConnectionDoc, tagDF map[string]int, total int) []string {
	out := make([]string, 0, len(doc.Tags))
	for _, tag := range doc.Tags {
		if novelConnectionDFSurvives(tagDF[tag], total) {
			out = append(out, tag)
		}
	}
	return out
}

func novelDFSurvivingAuthor(doc novelConnectionDoc, authorDF map[string]int, total int) string {
	author := strings.ToLower(strings.TrimSpace(doc.Author))
	if author == "" || !novelConnectionDFSurvives(authorDF[author], total) {
		return ""
	}
	return author
}

func novelConnectionMatches(seed novelConnectionDoc, docs []novelConnectionDoc, by map[string]bool, minOverlap int) []novelConnectionMatch {
	df := novelConnectionTermDF(docs)
	seedTerms := novelSignificantConnectionTerms(seed, df, len(docs))
	matches := make([]novelConnectionMatch, 0)
	for _, doc := range docs {
		if doc.ID == seed.ID {
			continue
		}
		shared := novelConnectionShared{Tags: make([]string, 0), Terms: make([]string, 0)}
		score := 0
		if by["tags"] {
			shared.Tags = novelSharedStrings(seed.Tags, doc.Tags)
			score += 2 * len(shared.Tags)
		}
		if by["author"] && seed.Author != "" && strings.EqualFold(seed.Author, doc.Author) {
			shared.Author = true
			score += 2
		}
		if by["terms"] {
			shared.Terms = novelSharedStrings(seedTerms, novelSignificantConnectionTerms(doc, df, len(docs)))
			score += len(shared.Terms)
		}
		if score >= minOverlap {
			matches = append(matches, novelConnectionMatch{ID: doc.ID, Title: doc.Title, Shared: shared, Overlap: score, Score: score})
		}
	}
	sort.Slice(matches, func(i, j int) bool {
		if matches[i].Score == matches[j].Score {
			return matches[i].Title < matches[j].Title
		}
		return matches[i].Score > matches[j].Score
	})
	return matches
}

type novelConnectionIdentity struct {
	url, title, author, host string
	saved                    time.Time
}

func novelConnectionIdentityOf(doc novelConnectionDoc) novelConnectionIdentity {
	normalized := novelConnectionURL(doc.URL)
	parsed, _ := url.Parse("https://" + normalized)
	host := ""
	if parsed != nil && normalized != "" {
		host = parsed.Hostname()
	}
	return novelConnectionIdentity{url: normalized, title: novelConnectionTitle(doc.Title), author: strings.ToLower(strings.TrimSpace(doc.Author)), host: host, saved: doc.SavedAt}
}

func novelNearDuplicateIdentities(a, b novelConnectionIdentity) bool {
	if a.url != "" && a.url == b.url {
		return true
	}
	if a.title == "" || a.title != b.title || !novelValidDedupeTitleKey(a.title) {
		return false
	}
	sameAuthor := a.author != "" && a.author == b.author
	if sameAuthor {
		return true
	}
	return a.host != "" && a.host == b.host && !a.saved.IsZero() && !b.saved.IsZero() && a.saved.Sub(b.saved).Abs() <= time.Hour
}

func novelNearDuplicateConnectionDocs(a, b novelConnectionDoc) bool {
	return novelNearDuplicateIdentities(novelConnectionIdentityOf(a), novelConnectionIdentityOf(b))
}

// novelSharedSorted intersects already sorted unique signals without per-pair maps.
func novelSharedSorted(a, b []string) []string {
	out := make([]string, 0)
	for i, j := 0, 0; i < len(a) && j < len(b); {
		switch {
		case a[i] < b[j]:
			i++
		case a[i] > b[j]:
			j++
		default:
			out = append(out, a[i])
			i++
			j++
		}
	}
	return out
}

func novelPairBetter(a, b novelConnectionPair) bool {
	if a.Score != b.Score {
		return a.Score > b.Score
	}
	if a.A.ID != b.A.ID {
		return a.A.ID < b.A.ID
	}
	return a.B.ID < b.B.ID
}

type novelPairHeap []novelConnectionPair

func (h novelPairHeap) Len() int           { return len(h) }
func (h novelPairHeap) Less(i, j int) bool { return novelPairBetter(h[j], h[i]) }
func (h novelPairHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *novelPairHeap) Push(v any)        { *h = append(*h, v.(novelConnectionPair)) }
func (h *novelPairHeap) Pop() any          { old := *h; v := old[len(old)-1]; *h = old[:len(old)-1]; return v }
func (h *novelPairHeap) keep(pair novelConnectionPair, top int) {
	if top <= 0 || h.Len() < top {
		heap.Push(h, pair)
		return
	}
	if novelPairBetter(pair, (*h)[0]) {
		(*h)[0] = pair
		heap.Fix(h, 0)
	}
}

func novelConnectionPostingsCap(total int) int {
	// Three postings preserve meaningful pairs in small libraries and the 15% boundary.
	relative := max(3, total/20)
	return min(novelLibraryWideSignalPostingsCap, relative)
}

func novelConnectionsLibraryWide(docs []novelConnectionDoc, by map[string]bool, minOverlap int, top int) ([]novelConnectionPair, []string, int) {
	total := len(docs)
	termDF := novelConnectionTermDF(docs)
	tagDF := novelConnectionTagDF(docs)
	authorDF := novelConnectionAuthorDF(docs)
	docTerms := make([][]string, len(docs))
	docTags := make([][]string, len(docs))
	docAuthors := make([]string, len(docs))
	identities := make([]novelConnectionIdentity, len(docs))
	index := map[string][]int{}
	for i, doc := range docs {
		identities[i] = novelConnectionIdentityOf(doc)
		docTerms[i] = novelSignificantConnectionTerms(doc, termDF, total)
		docTags[i] = novelDFSurvivingTags(doc, tagDF, total)
		sort.Strings(docTags[i])
		docAuthors[i] = novelDFSurvivingAuthor(doc, authorDF, total)
		if by["terms"] {
			for _, term := range docTerms[i] {
				index["term:"+term] = append(index["term:"+term], i)
			}
		}
		if by["tags"] {
			for _, tag := range docTags[i] {
				index["tag:"+tag] = append(index["tag:"+tag], i)
			}
		}
		if by["author"] && docAuthors[i] != "" {
			index["author:"+docAuthors[i]] = append(index["author:"+docAuthors[i]], i)
		}
	}

	signals := make([]string, 0, len(index))
	for signal := range index {
		signals = append(signals, signal)
	}
	sort.Strings(signals)
	visited := map[uint64]bool{}
	notes := make([]string, 0)
	pairs := make(novelPairHeap, 0)
	hiddenNearDuplicates := 0
	for _, signal := range signals {
		postings := index[signal]
		if len(postings) > novelConnectionPostingsCap(total) {
			notes = append(notes, fmt.Sprintf("%s (%d docs)", signal, len(postings)))
			continue
		}
		sort.Ints(postings)
		for x := 0; x < len(postings); x++ {
			for y := x + 1; y < len(postings); y++ {
				i, j := postings[x], postings[y]
				aIdx, bIdx := i, j
				if docs[aIdx].ID > docs[bIdx].ID {
					aIdx, bIdx = bIdx, aIdx
				}
				key := uint64(uint32(i))<<32 | uint64(uint32(j))
				if visited[key] {
					continue
				}
				visited[key] = true
				if novelNearDuplicateIdentities(identities[aIdx], identities[bIdx]) {
					hiddenNearDuplicates++
					continue
				}
				if novelLibraryWideScoreCandidateHook != nil {
					novelLibraryWideScoreCandidateHook(docs[aIdx], docs[bIdx])
				}
				shared := novelConnectionShared{Tags: make([]string, 0), Terms: make([]string, 0)}
				score := 0
				if by["tags"] {
					shared.Tags = novelSharedSorted(docTags[i], docTags[j])
					score += 2 * len(shared.Tags)
				}
				if by["author"] && docAuthors[i] != "" && docAuthors[i] == docAuthors[j] {
					shared.Author = true
					score += 2
				}
				if by["terms"] {
					shared.Terms = novelSharedSorted(docTerms[i], docTerms[j])
					score += len(shared.Terms)
				}
				if score >= minOverlap {
					pairs.keep(novelConnectionPair{
						A:       novelConnectionPairDoc{ID: docs[aIdx].ID, Title: docs[aIdx].Title},
						B:       novelConnectionPairDoc{ID: docs[bIdx].ID, Title: docs[bIdx].Title},
						Shared:  shared,
						Overlap: score,
						Score:   score,
					}, top)
				}
			}
		}
	}
	sort.Slice(pairs, func(i, j int) bool { return novelPairBetter(pairs[i], pairs[j]) })
	return pairs, notes, hiddenNearDuplicates
}

func novelLibraryWideNote(scanned int, total int, all bool, skipped []string, hiddenNearDuplicates int) string {
	kind := "engaged docs"
	if all {
		kind = "docs"
	}
	note := fmt.Sprintf("scanned %d %s", scanned, kind)
	if !all && total > scanned {
		note += fmt.Sprintf("; run --all to include %d more", total-scanned)
	}
	if len(skipped) > 0 {
		label := "signals"
		if len(skipped) == 1 {
			label = "signal"
		}
		note += fmt.Sprintf("; skipped %d over-common %s", len(skipped), label)
	}
	if hiddenNearDuplicates > 0 {
		label := "pairs"
		if hiddenNearDuplicates == 1 {
			label = "pair"
		}
		note += fmt.Sprintf("; hidden %d near-duplicate %s (see `dedupe`)", hiddenNearDuplicates, label)
	}
	return note
}

func novelRenderConnectionsMarkdown(w io.Writer, view novelConnectionsLibraryView) error {
	if view.Note != "" {
		if _, err := fmt.Fprintln(w, view.Note); err != nil {
			return err
		}
	}
	for _, pair := range view.Pairs {
		if _, err := fmt.Fprintf(w, "\n- %s (%s) <-> %s (%s) - score %d\n", pair.A.Title, pair.A.ID, pair.B.Title, pair.B.ID, pair.Score); err != nil {
			return err
		}
		if len(pair.Shared.Tags) > 0 {
			if _, err := fmt.Fprintf(w, "  - tags: %s\n", strings.Join(pair.Shared.Tags, ", ")); err != nil {
				return err
			}
		}
		if pair.Shared.Author {
			if _, err := fmt.Fprintln(w, "  - author: shared"); err != nil {
				return err
			}
		}
		if len(pair.Shared.Terms) > 0 {
			if _, err := fmt.Fprintf(w, "  - terms: %s\n", strings.Join(pair.Shared.Terms, ", ")); err != nil {
				return err
			}
		}
	}
	return nil
}

func newNovelConnectionsCmd(flags *rootFlags) *cobra.Command {
	var flagSeedDoc string
	var flagBy string
	var flagMinOverlap string
	var flagTop int
	var flagLibraryWide bool
	var flagAll bool

	cmd := &cobra.Command{
		Use:         "connections",
		Short:       "Surface non-obvious links between items you read months apart via shared tags, terms, and authors.",
		Example:     `  readwise-pp-cli connections --seed-doc 01abc --by tags,author,terms --min-overlap 2 --json`,
		Annotations: map[string]string{"mcp:read-only": "true", "mcp:read-flags": "db-path"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 && cmd.Flags().NFlag() == 0 {
				return usageErr(fmt.Errorf("connections needs --seed-doc <id> to find links to one document, or --library-wide to surface links across your engaged docs (get an id from 'read-next' or 'search')"))
			}
			if dryRunOK(flags) {
				if flags.asJSON {
					return writeDryRun(cmd.OutOrStdout(), flags, "connections")
				}
				return printDryRunNote(cmd, flags, "would find related documents by shared tags, authors, and terms")
			}
			if strings.TrimSpace(flagSeedDoc) != "" && flagLibraryWide {
				return usageErr(fmt.Errorf("choose one: --seed-doc or --library-wide"))
			}
			if strings.TrimSpace(flagSeedDoc) == "" && !flagLibraryWide {
				return usageErr(fmt.Errorf("connections needs --seed-doc <id> to find links to one document, or --library-wide to surface links across your engaged docs (get an id from 'read-next' or 'search')"))
			}
			if strings.TrimSpace(flagSeedDoc) != "" && flagAll {
				return usageErr(fmt.Errorf("--all only applies with --library-wide"))
			}
			by := novelCSVSet(flagBy, "tags,author,terms")
			minOverlap := 3
			if strings.TrimSpace(flagMinOverlap) != "" {
				n, err := strconv.Atoi(flagMinOverlap)
				if err != nil || n < 1 {
					_ = cmd.Usage()
					return usageErr(fmt.Errorf("--min-overlap must be a positive integer"))
				}
				minOverlap = n
			}
			if flagTop < 0 || (flagLibraryWide && flagAll && flagTop == 0) {
				return usageErr(fmt.Errorf("--top must be positive with --library-wide --all"))
			}
			if flagLibraryWide {
				exists, err := novelLocalStoreExists(cmd)
				if err != nil {
					return err
				}
				view := novelConnectionsLibraryView{Pairs: make([]novelConnectionPair, 0)}
				if !exists {
					view.Note = "No synced documents found. Run 'readwise-pp-cli sync' first."
					return printJSONFiltered(cmd.OutOrStdout(), view, flags)
				}
				db, err := novelOpenStore(cmd)
				if err != nil {
					return err
				}
				defer db.Close()
				docs, total, err := novelLoadEngagedDocs(db, flagAll)
				if err != nil {
					return err
				}
				view.Scanned = len(docs)
				if len(docs) == 0 {
					view.Note = "No synced documents found. Run 'readwise-pp-cli sync' first."
					return printJSONFiltered(cmd.OutOrStdout(), view, flags)
				}
				var skipped []string
				var hiddenNearDuplicates int
				view.Pairs, skipped, hiddenNearDuplicates = novelConnectionsLibraryWide(docs, by, minOverlap, flagTop)
				view.Note = novelLibraryWideNote(len(docs), total, flagAll, skipped, hiddenNearDuplicates)
				return printJSONFiltered(cmd.OutOrStdout(), view, flags)
			}
			docs, err := novelLoadConnectionDocs(cmd)
			if err != nil {
				return err
			}
			view := novelConnectionsView{Seed: map[string]string{"id": flagSeedDoc}, Matches: make([]novelConnectionMatch, 0)}
			if len(docs) == 0 {
				view.Note = "No synced documents found. Run 'readwise-pp-cli sync' first."
				return printJSONFiltered(cmd.OutOrStdout(), view, flags)
			}
			var seed novelConnectionDoc
			found := false
			for _, doc := range docs {
				if doc.ID == flagSeedDoc {
					seed = doc
					found = true
					break
				}
			}
			if !found {
				view.Seed["title"] = ""
				view.Note = fmt.Sprintf("seed document %s not found in local store; run 'readwise-pp-cli sync' or verify the id", flagSeedDoc)
				if !flags.asJSON && !flags.compact && !flags.csv && !flags.plain && !flags.quiet && isTerminal(cmd.OutOrStdout()) {
					fmt.Fprintln(cmd.OutOrStdout(), view.Note)
					return nil
				}
				return printJSONFiltered(cmd.OutOrStdout(), view, flags)
			}
			view.Seed["title"] = seed.Title
			view.Matches = novelConnectionMatches(seed, docs, by, minOverlap)
			if flagTop > 0 && len(view.Matches) > flagTop {
				view.Matches = view.Matches[:flagTop]
			}
			return printJSONFiltered(cmd.OutOrStdout(), view, flags)
		},
	}
	cmd.Flags().StringVar(&flagSeedDoc, "seed-doc", "", "Seed document id")
	cmd.Flags().StringVar(&flagBy, "by", "tags,author,terms", "Overlap signals to compare: tags,author,terms")
	cmd.Flags().StringVar(&flagMinOverlap, "min-overlap", "3", "Minimum weighted overlap score (tag=2, author=2, term=1; default 3)")
	cmd.Flags().IntVar(&flagTop, "top", 20, "Maximum results to return (seeded matches or library-wide pairs)")
	cmd.Flags().BoolVar(&flagLibraryWide, "library-wide", false, "Surface document pairs across engaged docs")
	cmd.Flags().BoolVar(&flagAll, "all", false, "With --library-wide, include every document instead of only engaged docs")
	cmd.Flags().String("db-path", "", "Database path (uses the local store by default)")
	return cmd
}

func novelConnectionURL(raw string) string {
	return novelNormalizeURL(raw)
}
func novelConnectionTitle(title string) string {
	for _, sep := range []string{" | ", " - ", " — "} {
		if i := strings.LastIndex(title, sep); i > 0 {
			title = title[:i]
		}
	}
	return novelNormalizeTitle(title)
}
